use std::{fs::File, os::unix::fs::FileExt, sync::{Arc, atomic::{AtomicU64, Ordering}}, time::Instant};
use qtrace_provider::{ArtifactDigest, FlightProvider, OperationAbort, ProviderError, ReadAtSource, SourceIdentity, TraceProvider, WorkDelta, WorkGuard};
use sha2::{Digest, Sha256};

struct Source(File, u64);
impl ReadAtSource for Source {
    fn len(&self) -> u64 { self.1 }
    fn read_exact_at(&self, offset: u64, output: &mut [u8]) -> Result<(), ProviderError> {
        self.0.read_exact_at(output, offset).map_err(|error| ProviderError::new("probe.io", "probe", None, false, error.to_string()))
    }
}

struct Guard { used: [AtomicU64; 6], limit: u64, profile: bool }
impl WorkGuard for Guard {
    fn consume(&self, delta: WorkDelta) -> Result<(), OperationAbort> {
        for (counter, value) in self.used.iter().zip([delta.input_bytes, delta.decompressed_bytes, delta.events, delta.nodes, delta.rows, delta.resident_bytes]) {
            counter.fetch_add(value, Ordering::Relaxed);
        }
        if self.profile && delta.resident_bytes >= 16 * 1024 * 1024 {
            eprintln!("allocation={}\n{}", delta.resident_bytes, std::backtrace::Backtrace::force_capture());
        }
        let consumed = self.used[5].load(Ordering::Relaxed);
        if consumed > self.limit {
            return Err(OperationAbort::budget_exceeded(qtrace_provider::BudgetDimension::ResidentBytes, self.limit, consumed));
        }
        Ok(())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut args = std::env::args().skip(1);
    let path = args.next().ok_or("artifact path required")?;
    let limit = args.next().map(|value| value.parse::<u64>()).transpose()?.unwrap_or(u64::MAX);
    let file = File::open(&path)?;
    let length = file.metadata()?.len();
    let guard = Guard { used: std::array::from_fn(|_| AtomicU64::new(0)), limit, profile: std::env::var_os("FLIGHT_PROFILE_ALLOCATIONS").is_some() };
    let identity = SourceIdentity { artifact: ArtifactDigest::new([0x66; 32]), format: "Flight".into(), format_major: 2, format_minor: 0, source_bytes: length };
    let started = Instant::now();
    let provider = FlightProvider::open(Arc::new(Source(file, length)), identity, &guard);
    let seconds = started.elapsed().as_secs_f64();
    let mut evidence = serde_json::json!({"source": path, "source_bytes": length, "open_seconds": seconds, "resident_limit": limit, "open_work": guard.used.iter().map(|counter| counter.load(Ordering::Relaxed)).collect::<Vec<_>>()});
    match provider {
        Ok(provider) => {
            let mut digest = Sha256::new();
            let mut events = 0_u64;
            let mut cursor = Box::new(provider).into_cursor()?;
            while let Some(event) = cursor.next_event(&guard)? {
                digest.update(serde_json::to_vec(&event)?);
                digest.update(b"\n");
                events += 1;
            }
            let summary = cursor.finish()?;
            digest.update(serde_json::to_vec(&summary)?);
            evidence["status"] = "passed".into();
            evidence["events"] = events.into();
            evidence["digest"] = format!("{:x}", digest.finalize()).into();
            evidence["summary"] = serde_json::to_value(summary)?;
            println!("{}", serde_json::to_string(&evidence)?);
        }
        Err(error) => {
            evidence["status"] = "failed".into();
            evidence["error"] = error.to_string().into();
            println!("{}", serde_json::to_string(&evidence)?);
            std::process::exit(1);
        }
    }
    Ok(())
}
